INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13066, 'koKR', 'Nestor Yurauk', '', '', '', '', '', '', '', '', 0),
(13207, 'koKR', 'Sale Kamienia', 'No proszę, nie spodziewałem się spotkać innych poszukiwaczy przygód w takim miejscu! Tak się składa, że przydałoby mi się trochę towarzystwa na to, co nas czeka.$b$bJeśli moje badania nad tymi salami są trafne, czekają tu na nas wiekopomne odkrycia!$b$bJeśli mogę liczyć, że będziesz mnie $gosłaniał:osłaniała;, możesz się przyłączyć. No to jak, $N? Idziesz ze mną?', 'Brann Miedziobrody chce, żebyś mu $gtowarzyszył:towarzyszyła;, gdy będzie odkrywał tajemnice Sal Kamienia.', '', 'Wróć do Branna Miedziobrodego w Salach Kamienia.', 'Wyprawa badawcza Branna zakończona', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13207, 'koKR', 'Zawsze więcej pytań niż odpowiedzi, co, $gchłopcze:dziewczyno;?\n', 0),
(13252, 'koKR', 'Czyż technologia tytanów nie jest niesamowita? Informacje są zawarte w samym dysku!$b$bMam tylko nadzieję, że wymyślimy, jak je z niego wydobyć.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13207, 'koKR', 'No, no, jednak dobrze się stało, żeśmy na siebie wpadli.', 0),
(13252, 'koKR', 'Masz dysk?', 0);
