INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(27589, 'koKR', 'Teraz jest ciut trudniej niż przedtem... O, do diabła... nadchodzą!', '', 0),
(27590, 'koKR', 'Na Madorana, co TO niby zrobiło? O! Chwila, już prawie mam...', '', 0),
(27591, 'koKR', 'Ha, udało się! Pomoc nadchodzi! Masz, ty jarzący się żelazny bydlaku!', '', 0),
(28121, 'koKR', 'Jestem cały połamany... mogę... z tego nie wyjść.', '', 0),
(28591, 'koKR', 'Loken?! To ci dopiero kłopot... Może i unieszkodliwiliśmy żelazne krasnoludy, ale idę o zakład, że gdzieś indziej jest jeszcze jedna maszyna, która wypluwa całą masę tych żelaznych wrykulów!', '', 0),
(29556, 'koKR', 'Zmiażdżę...', '', 0),
(29558, 'koKR', 'Ha... ha... ha...', '', 0),
(29559, 'koKR', 'Złamię... was...', '', 0),
(29560, 'koKR', 'Uuuuchhhhhhhh...', '', 0),
(29563, 'koKR', '', 'Nie trzeba było tu przychodzić... teraz zginiecie!', 0),
(29564, 'koKR', '', 'Dlaczego tak musi być?', 0),
(29566, 'koKR', '', 'Należało wam się!', 0),
(29567, 'koKR', '', 'Mój ciężar staje się coraz większy...', 0),
(29568, 'koKR', '', 'To wasza wina!', 0),
(29570, 'koKR', '', 'Tyle straconego czasu... którego już nigdy nie odzyskacie!', 0),
(29574, 'koKR', '', 'Obyście wszyscy zgnili! Nigdy... tego... nie chciałam.', 0),
(29582, 'koKR', 'Miękkie, wrażliwe skorupy. Krótkie, kruche życia. Nie uciekniecie przed Klątwą Ciała!', '', 0),
(29583, 'koKR', 'Folvynn buul hrom onn!', '', 0),
(29584, 'koKR', 'Ciało nie ma szans z żelazem!', '', 0),
(29585, 'koKR', 'Armie żelaza zadławią świat!', '', 0),
(29586, 'koKR', 'Loken nie spocznie... dopóki kuźnia nie zostanie odbita! Niczego... nie zmienicie!', '', 0),
(30522, 'koKR', 'Jeszcze nie... jeszcze n--', '', 0),
(30523, 'koKR', 'Poświęć chwilę i rozkoszuj się tym razem ze mną. Wkrótce... wszystko się wyjaśni. No dobra, do dzieła!', '', 0),
(30525, 'koKR', 'No, to się nazywa zapracować na kolację!', '', 0),
(30526, 'koKR', 'Naprzód, tak trzymać!', '', 0),
(30552, 'koKR', 'Teraz miejcie oczy otwarte! Uporam się z tym, zanim kot zdąży machnąć ogo--', '', 0),
(30553, 'koKR', 'Oho, to nie brzmi dobrze. Możemy mieć komplikację albo dwie...', '', 0),
(30554, 'koKR', 'A, chcesz grać twardo, co? To akurat moja specjalność!', '', 0),
(30555, 'koKR', 'Jeszcze parę minut i--', '', 0),
(30556, 'koKR', 'Podwyższony? A jakie są dobre wieści?', '', 0),
(30557, 'koKR', 'Więc w tym był problem? Teraz robię postępy...', '', 0),
(30558, 'koKR', 'Chwila! Nikt tu nie zostanie zdezynfekowany, dopóki mam coś do powiedzenia!', '', 0),
(30559, 'koKR', 'Ha! Stare magiczne paluszki wreszcie dały radę! A teraz bierzmy się do--', '', 0),
(30560, 'koKR', 'Czystka? Nie, nie, nie, nie, nie... gdzie ja-- Aha, to powinno załatwić sprawę...', '', 0),
(30561, 'koKR', 'Pora zdobyć trochę odpowiedzi! Zaczynamy przedstawienie!', '', 0),
(30562, 'koKR', 'Robię, co mogę!', '', 0),
(30563, 'koKR', 'Niech was Światłość chroni!', '', 0),
(30564, 'koKR', 'Mam nadzieję, że to wszystko jest tego warte!', '', 0),
(30565, 'koKR', 'Zapytanie? A po co niby tu jestem, na herbatkę i ciasteczka? Wykrztuś to wreszcie!', '', 0),
(30566, 'koKR', 'Powiedz mi, jak powstały krasnoludy, i zacznij od początku!', '', 0),
(30567, 'koKR', 'Dobra, dobra... Wiem, że ziemnych stworzono z kamienia, by kształtowali głębiny świata. Ale co z anomaliami? Niestabilizująca się matryca i tak dalej?', '', 0),
(30568, 'koKR', 'Nekro-co-do-licha-- Mów wreszcie we wspólnym, dobra?', '', 0),
(30577, 'koKR', 'Przedwieczni, co? Więc potraktowali ziemnych tą Klątwą Ciała... i co dalej?', '', 0),
(30578, 'koKR', 'Gdyby zabili Przedwiecznych, Azeroth zostałoby zniszczone...', '', 0),
(30579, 'koKR', 'Jacy obrońcy?', '', 0),
(30580, 'koKR', 'Aesir i Vanir... Dobra, więc Kuźnia Woli zaczęła tworzyć nowych ziemnych... ale co się stało ze starymi?', '', 0),
(30581, 'koKR', 'Wszystko wstrzymać! Aesir i Vanir poszli na wojnę? Dlaczego?', '', 0),
(30582, 'koKR', 'Ten cały „Loken” wygląda na paskudnego typa. Dobrze, że nie musimy się już martwić takimi jak on. Więc... jeśli dobrze cię rozumiem, pierwotni ziemni w końcu przebudzili się z tego zastoju, a do tego czasu ta cała destabili-coś-tam zmieniła ich w prawdziwe krasnoludy. A przynajmniej... w przodków krasnoludów.', '', 0),
(30583, 'koKR', 'No, no... sporo tego do przetrawienia. Będę potrzebował trochę czasu, żeby to wszystko ogarnąć. Dziękuję.', '', 0),
(30584, 'koKR', 'Użyję kuźni, by stworzyć zastępy ziemnych, którzy będą stać na straży... Ale nasze największe wyzwanie wciąż przed nami: odnaleźć i powstrzymać Lokena!', '', 0),
(31555, 'koKR', 'Bez obaw! Stary Brann was osłania! Zajmijcie czymś to metalowe monstrum, a ja zobaczę, czy nie zdołam namówić tej maszyny, żeby wam pomogła!', '', 0),
(31660, 'koKR', 'Myślę, że czas zobaczyć, co jest za drzwiami przy wejściu. Zakradnę się tam po cichutku. Spotkajmy się przy drzwiach, a ja nas wpuszczę.', '', 0);
